        "g",
        "",
        "comm-ethiopian",
        "Tewahedo — Athanasius of Alexandria",
        "Athanasius of Alexandria (350).",
        '<aside class="note-comm-ethiopian"><strong>Athanasius of Alexandria</strong> <em>Orationes contra Arianos II.79</em> <small>(c. 350 AD)</small><p>&#x27;And he was clothed with a vesture dipped in blood: and his name is called The Word of God&#x27; — Athanasius marks kekletai to onoma autou ho Logos tou theou (his name is-called The Word-of-God) as the APOCALYPTIC LOGOS-CONFIRMATION of the Johannine-prologue. Where Jn 1:1 opens the gospel with en archē ēn ho Logos, kai ho Logos ēn pros ton theon, kai theos ēn ho Logos (in-the-beginning was-the-Word, and the-Word was-with God, and God-was the-Word), Rev 19:13 closes the canonical-Revelation-cycle with the same Word-name-on-the-eschatological-Christ. The vesture-dipped-in-blood (himation bebammenon haimati) carries the Paschal-cross-blood into the eschatological-victory; the Word-of-God-name carries the Johannine-pre-temporal-deity into the eschatological-glory. Tewahedo eschatological-iconography depicts the returning-Christ in vesture-with-Paschal-blood + Logos-name explicitly cited.</p></aside>',
        "Athanasius of Alexandria, Orationes contra Arianos (Four Discourses Against the Arians, I-IV), in Select Writings and Letters of Athanasius, Nicene and Post-Nicene Fathers (NPNF), Series 2, Vol. 4, ed. Archibald Robertson (Oxford / T&T Clark, 1892). PD. Greek text in Migne PG 26 (1857).",
